/**
 * Managed policy in code (docs/AGENT-GUARD.md): the one mechanism a session cannot switch off (tested: a managed hook survived `--settings disableAllHooks`,
 * `--setting-sources user` and a project `disableAllHooks`), generated in every documented delivery format so that, when the plan exists, activation is ONE step.
 *
 *   Claude Code   (code.claude.com/docs/en/managed-settings, server-managed-settings)
 *     file        /etc/claude-code/managed-settings.json (Linux, WSL) · /Library/Application Support/ClaudeCode/managed-settings.json (macOS) ·
 *                 C:\Program Files\ClaudeCode\managed-settings.json (Windows); an optional managed-settings.d/ directory beside it
 *     MDM         macOS: the com.anthropic.claudecode managed-preferences domain (a plist with the same top-level keys; Jamf, Iru and Intune templates wrap it in a
 *                 configuration profile) · Windows: HKLM\SOFTWARE\Policies\ClaudeCode, value `Settings` (REG_SZ holding the JSON)
 *     server      claude.ai, Organization settings, Claude Code, Managed settings: the same JSON (Team or Enterprise plan, Owner role); reaches Anthropic-hosted cloud sessions
 *   Codex         requirements.toml with [[hooks.EVENT]] and [[hooks.EVENT.hooks]] (learn.chatgpt.com/docs/hooks; the syntax is from that page's one example and
 *                 its location is the Codex admin documentation's: not verified here)
 * The hook command is the launcher (launcher.sh) inline: it finds the repository a call is about and hands it to that repository's hook client.
 */
import { execFileSync, spawnSync } from "node:child_process";
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { gitEnv } from "../git.js";
import { LAUNCH_SHIM, shimText } from "./install.js";

const HERE = dirname(fileURLToPath(import.meta.url));
export const EVENTS = { SessionStart: "startup|resume|clear|compact", UserPromptSubmit: null, PreToolUse: "*", SubagentStart: null, SubagentStop: null, ConfigChange: "project_settings|local_settings|user_settings" };
const CODEX_EVENTS = ["SessionStart", "UserPromptSubmit", "PreToolUse", "SubagentStart", "SubagentStop"];

/** launcher.sh without its comment header, as one single-quoted `bash -c` command (safe in JSON, a plist, a .reg value and a TOML string). */
export function launcherCommand() {
  const src = readFileSync(join(HERE, "launcher.sh"), "utf8").split("\n").filter((l) => !/^\s*#/.test(l) || l.startsWith("#!")).slice(1).join("\n").trim();
  return `bash -c '${src.replace(/'/g, `'\\''`)}'`;
}

export function claudeSettings(command = launcherCommand()) {
  const hook = (matcher) => ({ ...(matcher ? { matcher } : {}), hooks: [{ type: "command", command, timeout: 10 }] });
  return { forceRemoteSettingsRefresh: true, hooks: Object.fromEntries(Object.entries(EVENTS).map(([ev, m]) => [ev, [hook(m)]])) };
}

const xml = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const plistValue = (v, ind) => {
  const pad = "  ".repeat(ind);
  if (typeof v === "boolean") return `${pad}<${v}/>`;
  if (typeof v === "number") return `${pad}<integer>${v}</integer>`;
  if (typeof v === "string") return `${pad}<string>${xml(v)}</string>`;
  if (Array.isArray(v)) return `${pad}<array>\n${v.map((x) => plistValue(x, ind + 1)).join("\n")}\n${pad}</array>`;
  return `${pad}<dict>\n${Object.entries(v).map(([k, x]) => `${pad}  <key>${xml(k)}</key>\n${plistValue(x, ind + 1)}`).join("\n")}\n${pad}</dict>`;
};
export const plist = (settings) => `<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n<plist version="1.0">\n${plistValue(settings, 0)}\n</plist>\n`;
export const regFile = (settings) => `Windows Registry Editor Version 5.00\r\n\r\n[HKEY_LOCAL_MACHINE\\SOFTWARE\\Policies\\ClaudeCode]\r\n"Settings"="${JSON.stringify(settings).replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"\r\n`;
export function codexToml(command = launcherCommand()) {
  const q = (s) => JSON.stringify(s);
  return ["# generated by kit agent-guard managed: Codex managed hooks (requirements.toml)", "allow_managed_hooks_only = true", "",
    ...CODEX_EVENTS.flatMap((ev) => [`[[hooks.${ev}]]`, ...(ev === "PreToolUse" ? ['matcher = ".*"'] : []), `[[hooks.${ev}.hooks]]`, 'type = "command"', `command = ${q(command)}`, "timeout = 10", ""])].join("\n");
}

export const ACTIVATE = `# Activating the enforcement the plan allows (owner)

Everything below is generated by \`kit agent-guard managed --out <dir>\` and checked by \`kit agent-guard managed --verify\`. Pick the channel; each is ONE step.

| Channel | One step |
| --- | --- |
| Claude Code, organisation-wide, including Anthropic-hosted cloud sessions (Team or Enterprise plan, Owner role) | claude.ai, Organization settings, Claude Code, Managed settings: paste \`server/server-managed-settings.json\`, save. Clients fetch it at startup and hourly; it cannot be switched off by user, project or \`--settings\` values. |
| Claude Code on a Linux or WSL machine | copy \`linux/etc/claude-code/managed-settings.json\` to \`/etc/claude-code/managed-settings.json\` (root). |
| Claude Code on macOS | copy \`macos/Library/Application Support/ClaudeCode/managed-settings.json\` into place, or deploy \`macos/com.anthropic.claudecode.plist\` as the \`com.anthropic.claudecode\` managed-preferences domain with Jamf, Iru or Intune (wrap it in a configuration profile with their template). |
| Claude Code on Windows | copy \`windows/Program Files/ClaudeCode/managed-settings.json\` to \`C:\\Program Files\\ClaudeCode\\\`, or import \`windows/claude-code-managed.reg\` (HKLM, value Settings) by Group Policy or Intune. Hook commands are bash: Claude Code on Windows runs them through Git Bash. |
| Codex | place \`codex/requirements.toml\` where the Codex admin documentation says managed requirements live. |

Until then, nothing is forced on an account without the plan: the repository hooks run only in a session that loads them, and \`--bare\`, \`--safe-mode\`, \`--setting-sources\` and \`--settings\` switch them off.
`;

/** Every generated file: { relative path: text }. */
export function bundle() {
  const command = launcherCommand(), s = claudeSettings(command), json = `${JSON.stringify(s, null, 2)}\n`;
  return {
    "linux/etc/claude-code/managed-settings.json": json,
    "macos/Library/Application Support/ClaudeCode/managed-settings.json": json,
    "windows/Program Files/ClaudeCode/managed-settings.json": json,
    "macos/com.anthropic.claudecode.plist": plist(s),
    "windows/claude-code-managed.reg": regFile(s),
    "server/server-managed-settings.json": json,
    "codex/requirements.toml": codexToml(command),
    "ACTIVATE.md": ACTIVATE,
  };
}
export function writeBundle(out) { const b = bundle(); for (const [f, t] of Object.entries(b)) { mkdirSync(dirname(join(out, f)), { recursive: true }); writeFileSync(join(out, f), t); } return Object.keys(b); }

/** Verify what was generated, structurally and by RUNNING the hook command: → problems. */
export function verifyBundle(kitRoot) {
  const problems = [], b = bundle();
  const s = JSON.parse(b["server/server-managed-settings.json"]);
  for (const f of ["linux/etc/claude-code/managed-settings.json", "macos/Library/Application Support/ClaudeCode/managed-settings.json", "windows/Program Files/ClaudeCode/managed-settings.json"]) if (b[f] !== b["server/server-managed-settings.json"]) problems.push(`${f} differs from the server payload`);
  for (const ev of Object.keys(EVENTS)) if (!s.hooks[ev]?.[0]?.hooks?.[0]?.command) problems.push(`managed settings have no hook for ${ev}`);
  if (s.disableAllHooks) problems.push("managed settings disable hooks");
  const cmd = s.hooks.PreToolUse[0].hooks[0].command;
  if (!b["codex/requirements.toml"].includes("allow_managed_hooks_only = true") || (b["codex/requirements.toml"].match(/^\[\[hooks\.\w+\]\]$/gm) || []).length !== CODEX_EVENTS.length) problems.push("the Codex requirements.toml is not well formed");
  if (!b["macos/com.anthropic.claudecode.plist"].includes("<key>hooks</key>") || !b["macos/com.anthropic.claudecode.plist"].includes("<key>PreToolUse</key>")) problems.push("the plist lacks the hooks");
  if (!/\[HKEY_LOCAL_MACHINE\\SOFTWARE\\Policies\\ClaudeCode\]\r\n"Settings"=".*"\r\n$/s.test(b["windows/claude-code-managed.reg"])) problems.push("the .reg file is not well formed");
  // run it: a repository with the guard pack denies, a repository without it refuses a write
  const tmp = mkdtempSync(join(tmpdir(), "kit-managed-"));
  try {
    const mk = (guard) => { const r = mkdtempSync(join(tmp, "r")); execFileSync("git", ["-C", r, "init", "-q"], { env: gitEnv() }); if (guard) { for (const [src, dst] of [["packages/cli/src", "packages/cli/src"], ["packages/core/registry", "packages/core/registry"], ["packages/cli/package.json", "packages/cli/package.json"], ["packages/core/package.json", "packages/core/package.json"]]) cpSync(join(kitRoot, src), join(r, dst), { recursive: true }); mkdirSync(join(r, dirname(LAUNCH_SHIM)), { recursive: true }); writeFileSync(join(r, LAUNCH_SHIM), shimText("packages/cli/src/agent-guard/daemon.mjs")); } return r; };
    const run = (cwd, tool, input) => spawnSync("sh", ["-c", cmd], { cwd, input: JSON.stringify({ hook_event_name: "PreToolUse", cwd, tool_name: tool, tool_input: input }), encoding: "utf8", env: { ...process.env, CLAUDE_PROJECT_DIR: "" } });
    const g = mk(true), n = mk(false);
    const a = run(g, "Bash", { command: "git push --force origin b" });
    if (a.status !== 0 || !/permissionDecision":"deny/.test(a.stdout)) problems.push(`the managed hook did not deny a force-push in a repository with the guard (exit ${a.status}): ${(a.stderr || a.stdout).slice(0, 120)}`);
    const w = run(n, "Write", { file_path: join(n, "a.js"), content: "x" });
    if (w.status !== 2) problems.push(`the managed hook did not hold a write in a repository with no guard pack (exit ${w.status})`);
    const rd = run(n, "Read", { file_path: join(n, "a.js") });
    if (rd.status !== 0) problems.push(`the managed hook blocked a read in a repository with no guard pack (exit ${rd.status})`);
    try { for (const r of [g]) spawnSync("node", [join(r, "packages/cli/src/agent-guard/daemon.mjs"), "stop"], { env: { ...process.env, CLAUDE_PROJECT_DIR: r } }); } catch { /* the tool is unavailable or found nothing: the caller handles the empty answer */ }
  } finally { rmSync(tmp, { recursive: true, force: true }); }
  return problems;
}
